--- a/memo.bugs.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/memo.bugs.test.ts	2026-10-29 16:18:03.463119141 +0000
@@ -0,0 +1,194 @@
+import { expect, test } from "bun:test";
+import { memo } from "./memo";
+
+function deferred<T>() {
+  let resolve!: (v: T) => void;
+  let reject!: (e: unknown) => void;
+  const promise = new Promise<T>((res, rej) => ((resolve = res), (reject = rej)));
+  return { promise, resolve, reject };
+}
+
+function lookups() {
+  const calls: { key: string; d: ReturnType<typeof deferred<string>> }[] = [];
+  const fn = (key: string) => {
+    const d = deferred<string>();
+    calls.push({ key, d });
+    return d.promise;
+  };
+  return { fn, calls };
+}
+
+const tick = () => new Promise((r) => setTimeout(r, 0));
+
+test("a result is kept for ttlMs from when it settled, not from when it was called", async () => {
+  let t = 0;
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 100, max: 10, now: () => t });
+  m("k");
+  t = 50;
+  calls[0]!.d.resolve("v");
+  await tick();
+  t = 149;
+  expect(await m("k")).toBe("v");
+  expect(calls).toHaveLength(1);
+  t = 150;
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a rejection is shared by waiting callers and not kept", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const a = m("k");
+  const b = m("k");
+  calls[0]!.d.reject(new Error("boom"));
+  await expect(a).rejects.toThrow("boom");
+  await expect(b).rejects.toThrow("boom");
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a late rejection does not delete a newer entry for the key", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const first = m("k");
+  m.invalidate("k");
+  m("k");
+  calls[0]!.d.reject(new Error("late"));
+  await expect(first).rejects.toThrow("late");
+  await tick();
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a late fulfilment after invalidate does not bring the old value back", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const first = m("k");
+  m.invalidate("k");
+  const second = m("k");
+  calls[1]!.d.resolve("new");
+  expect(await second).toBe("new");
+  calls[0]!.d.resolve("old");
+  expect(await first).toBe("old");
+  await tick();
+  expect(await m("k")).toBe("new");
+  expect(calls).toHaveLength(2);
+});
+
+test("a late fulfilment after clear does not bring the value back", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const first = m("k");
+  m.clear();
+  calls[0]!.d.resolve("old");
+  await first;
+  await tick();
+  expect(m.size).toBe(0);
+});
+
+test("a late fulfilment for an evicted key does not bring it back or grow past max", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 1 });
+  m("a");
+  m("b");
+  calls[0]!.d.resolve("a");
+  await tick();
+  expect(m.size).toBe(1);
+});
+
+test("size stays at or under max while calls are in flight and after they settle", async () => {
+  for (let max = 1; max <= 5; max++) {
+    const { fn, calls } = lookups();
+    const m = memo(fn, { ttlMs: 1000, max });
+    for (let i = 0; i < 10; i++) {
+      m(`k${i}`);
+      expect(m.size).toBeLessThanOrEqual(max);
+    }
+    for (const c of calls) c.d.resolve(c.key);
+    await tick();
+    expect(m.size).toBeLessThanOrEqual(max);
+  }
+});
+
+test("a cache hit counts as a use for least-recently-used eviction", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  m("a");
+  m("b");
+  for (const c of calls) c.d.resolve(c.key);
+  await tick();
+  void m("a");
+  m("c");
+  expect(calls).toHaveLength(3);
+  m("a");
+  expect(calls).toHaveLength(3);
+  m("b");
+  expect(calls).toHaveLength(4);
+});
+
+test("settling is not a use for least-recently-used eviction", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  m("a");
+  m("b");
+  calls[1]!.d.resolve("b");
+  calls[0]!.d.resolve("a");
+  await tick();
+  m("c");
+  m("a");
+  expect(calls).toHaveLength(4);
+});
+
+test("expired entries are not counted in size or against max", async () => {
+  let t = 0;
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 100, max: 2, now: () => t });
+  m("a");
+  m("b");
+  for (const c of calls) c.d.resolve(c.key);
+  await tick();
+  t = 100;
+  expect(m.size).toBe(0);
+  m("c");
+  m("d");
+  for (const c of calls.slice(2)) c.d.resolve(c.key);
+  await tick();
+  expect(m.size).toBe(2);
+  m("c");
+  m("d");
+  expect(calls).toHaveLength(4);
+});
+
+test("a settled value is passed through unchanged on a hit", async () => {
+  const obj = { n: 1 };
+  const m = memo(async () => obj, { ttlMs: 1000, max: 10 });
+  expect(await m("k")).toBe(obj);
+  await tick();
+  expect(await m("k")).toBe(obj);
+});
+
+test("the constructor rejects a max below 1 or not whole, and a ttlMs not above 0", () => {
+  const fn = async () => "v";
+  expect(() => memo(fn, { ttlMs: 1, max: 0 })).toThrow(RangeError);
+  expect(() => memo(fn, { ttlMs: 1, max: 1.5 })).toThrow(RangeError);
+  expect(() => memo(fn, { ttlMs: 0, max: 1 })).toThrow(RangeError);
+});
+
+test("a call whose fn throws synchronously evicts nothing", async () => {
+  const runs: string[] = [];
+  const fn = (key: string) => {
+    runs.push(key);
+    if (key === "x") throw new Error("s");
+    return Promise.resolve(key);
+  };
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  await m("a");
+  await m("b");
+  await tick();
+  expect(() => m("x")).toThrow("s");
+  expect(m.size).toBe(2);
+  await m("a");
+  await m("b");
+  expect(runs).toEqual(["a", "b", "x"]);
+});
