@@ -0,0 +1,244 @@
+import { expect, test } from "bun:test";
+import { memo } from "./memo";
+
+function deferred<T>() {
+  let resolve!: (v: T) => void;
+  let reject!: (e: unknown) => void;
+  const promise = new Promise<T>((res, rej) => ((resolve = res), (reject = rej)));
+  return { promise, resolve, reject };
+}
+
+// fn's calls, each settled by the test.
+function lookups() {
+  const calls: { key: string; d: ReturnType<typeof deferred<string>> }[] = [];
+  const fn = (key: string) => {
+    const d = deferred<string>();
+    calls.push({ key, d });
+    return d.promise;
+  };
+  return { fn, calls };
+}
+
+const tick = () => new Promise((r) => setTimeout(r, 0));
+
+test("a result is kept for ttlMs from when it settled, not from when it was called", async () => {
+  let t = 0;
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 100, max: 10, now: () => t });
+  m("k");
+  t = 50;
+  calls[0]!.d.resolve("v");
+  await tick();
+  t = 149;
+  expect(await m("k")).toBe("v");
+  expect(calls).toHaveLength(1);
+  t = 150;
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a rejection reaches every caller waiting on it and is not kept", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const a = m("k");
+  const b = m("k");
+  const err = new Error("boom");
+  calls[0]!.d.reject(err);
+  await expect(a).rejects.toBe(err);
+  await expect(b).rejects.toBe(err);
+  await tick();
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a rejection of an invalidated call does not delete the newer entry for its key", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const old = m("k");
+  m.invalidate("k");
+  m("k");
+  const err = new Error("boom");
+  calls[0]!.d.reject(err);
+  await expect(old).rejects.toBe(err);
+  await tick();
+  expect(m.size).toBe(1);
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("never keeps more than max keys, even when they are all in flight", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  m("a");
+  m("b");
+  m("c");
+  expect(m.size).toBe(2);
+  m("a");
+  expect(calls).toHaveLength(4);
+});
+
+test("a cache hit counts as a use for least recently used eviction", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  m("a");
+  m("b");
+  calls[0]!.d.resolve("a");
+  calls[1]!.d.resolve("b");
+  await tick();
+  m("a");
+  expect(calls).toHaveLength(2);
+  m("c");
+  expect(calls).toHaveLength(3);
+  m("a");
+  expect(calls).toHaveLength(3);
+  m("b");
+  expect(calls).toHaveLength(4);
+});
+
+test("settling a call is not a use for least recently used eviction", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  m("a");
+  m("b");
+  calls[1]!.d.resolve("b");
+  calls[0]!.d.resolve("a");
+  await tick();
+  m("c");
+  m("b");
+  expect(calls).toHaveLength(3);
+  m("a");
+  expect(calls).toHaveLength(4);
+});
+
+test("a call whose key was dropped to stay under max is not kept when it settles", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  const a = m("a");
+  m("b");
+  m("c");
+  calls[0]!.d.resolve("a");
+  expect(await a).toBe("a");
+  await tick();
+  expect(m.size).toBe(2);
+  m("a");
+  expect(calls).toHaveLength(4);
+});
+
+test("a call whose key was cleared is not kept when it settles", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const a = m("a");
+  m.clear();
+  calls[0]!.d.resolve("a");
+  expect(await a).toBe("a");
+  await tick();
+  expect(m.size).toBe(0);
+  m("a");
+  expect(calls).toHaveLength(2);
+});
+
+test("after invalidate during a call, each caller gets its own value and the newer one is kept", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const old = m("k");
+  m.invalidate("k");
+  const fresh = m("k");
+  calls[1]!.d.resolve("new");
+  calls[0]!.d.resolve("old");
+  expect(await old).toBe("old");
+  expect(await fresh).toBe("new");
+  await tick();
+  expect(await m("k")).toBe("new");
+  expect(calls).toHaveLength(2);
+});
+
+test("a synchronous throw from fn rejects the caller and is not kept", async () => {
+  const err = new Error("sync");
+  let runs = 0;
+  const m = memo(
+    (_key: string): Promise<string> => {
+      runs++;
+      throw err;
+    },
+    { ttlMs: 1000, max: 10 },
+  );
+  await expect(m("k")).rejects.toBe(err);
+  expect(m.size).toBe(0);
+  await expect(m("k")).rejects.toBe(err);
+  expect(runs).toBe(2);
+});
+
+test("matches a reference model over random operations", async () => {
+  const TTL = 10;
+  const KEYS = ["a", "b", "c", "d", "e"];
+  let seed = 12345;
+  const rand = (n: number) => {
+    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
+    return seed % n;
+  };
+
+  for (let run = 0; run < 200; run++) {
+    let t = 0;
+    const max = 1 + rand(3);
+    const { fn, calls } = lookups();
+    const m = memo(fn, { ttlMs: TTL, max, now: () => t });
+    // Reference: entries in least recently used order; `call` is the index into fn's calls.
+    let model: { key: string; call: number; settled: boolean; expires: number }[] = [];
+    let modelRuns = 0;
+    const settled = new Set<number>();
+    const answers: { key: string; p: Promise<string> }[] = [];
+    const settle = (i: number, ok: boolean) => {
+      const e = model.find((x) => x.call === i);
+      if (!e) return;
+      if (ok) {
+        e.settled = true;
+        e.expires = t + TTL;
+      } else model = model.filter((x) => x !== e);
+    };
+
+    for (let op = 0; op < 30; op++) {
+      const kind = rand(5);
+      if (kind === 0) {
+        const key = KEYS[rand(KEYS.length)]!;
+        const idx = model.findIndex((x) => x.key === key);
+        if (idx >= 0 && (!model[idx]!.settled || model[idx]!.expires > t)) {
+          const [e] = model.splice(idx, 1);
+          model.push(e!);
+        } else {
+          if (idx >= 0) model.splice(idx, 1);
+          while (model.length >= max) model.shift();
+          model.push({ key, call: modelRuns++, settled: false, expires: Infinity });
+        }
+        answers.push({ key, p: m(key) });
+      } else if (kind === 1 && calls.length > 0) {
+        const i = rand(calls.length);
+        if (settled.has(i)) continue;
+        settled.add(i);
+        const ok = rand(2) === 0;
+        if (ok) calls[i]!.d.resolve(calls[i]!.key);
+        else calls[i]!.d.reject(new Error("x"));
+        settle(i, ok);
+        await tick();
+      } else if (kind === 2) {
+        t += rand(TTL + 1);
+      } else if (kind === 3) {
+        const key = KEYS[rand(KEYS.length)]!;
+        m.invalidate(key);
+        model = model.filter((x) => x.key !== key);
+      } else {
+        m.clear();
+        model = [];
+      }
+      expect(m.size).toBe(model.length);
+      expect(calls).toHaveLength(modelRuns);
+    }
+    // Settle the calls still pending, so every caller's promise can be awaited and none is left unhandled.
+    calls.forEach((c, i) => {
+      if (!settled.has(i)) c.d.resolve(c.key);
+    });
+    const outcomes = await Promise.allSettled(answers.map((a) => a.p));
+    outcomes.forEach((o, i) => {
+      if (o.status === "fulfilled") expect(o.value).toBe(answers[i]!.key);
+    });
+  }
+});
