diff -ruN '--exclude=node_modules' '--exclude=.git' a/memo.bugs.test.ts b/memo.bugs.test.ts
--- a/memo.bugs.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/memo.bugs.test.ts	2026-10-29 16:22:43.155135767 +0000
@@ -0,0 +1,235 @@
+import { expect, test } from "bun:test";
+import { memo } from "./memo";
+
+function deferred<T>() {
+  let resolve!: (v: T) => void;
+  let reject!: (e: unknown) => void;
+  const promise = new Promise<T>((res, rej) => ((resolve = res), (reject = rej)));
+  return { promise, resolve, reject };
+}
+
+// fn's calls, each settled by the test.
+function lookups() {
+  const calls: { key: string; d: ReturnType<typeof deferred<string>> }[] = [];
+  const fn = (key: string) => {
+    const d = deferred<string>();
+    calls.push({ key, d });
+    return d.promise;
+  };
+  return { fn, calls };
+}
+
+const tick = () => new Promise((r) => setTimeout(r, 0));
+
+test("different keys in flight each get their own lookup", () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  m("a");
+  m("b");
+  expect(calls.map((c) => c.key)).toEqual(["a", "b"]);
+});
+
+test("ttl counts from when the result settled, not when the call started", async () => {
+  let t = 0;
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 100, max: 10, now: () => t });
+  m("k");
+  t = 50;
+  calls[0]!.d.resolve("v");
+  await tick();
+  t = 149;
+  m("k");
+  expect(calls).toHaveLength(1);
+  t = 150;
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a rejection reaches every waiting caller and is not kept", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const a = m("k");
+  const b = m("k");
+  const err = new Error("boom");
+  calls[0]!.d.reject(err);
+  await expect(a).rejects.toBe(err);
+  await expect(b).rejects.toBe(err);
+  expect(m.size).toBe(0);
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a stale rejection does not drop a newer entry for the key", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const first = m("k");
+  m.invalidate("k");
+  m("k");
+  expect(calls).toHaveLength(2);
+  const err = new Error("old");
+  calls[0]!.d.reject(err);
+  await expect(first).rejects.toBe(err);
+  expect(m.size).toBe(1);
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a stale result in flight during invalidate is not kept after it settles", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  m("k");
+  m.invalidate("k");
+  calls[0]!.d.resolve("old");
+  await tick();
+  expect(m.size).toBe(0);
+  m("k");
+  expect(calls).toHaveLength(2);
+});
+
+test("a result settled after clear is not kept", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  m("a");
+  m("b");
+  m.clear();
+  calls[0]!.d.resolve("a");
+  calls[1]!.d.resolve("b");
+  await tick();
+  expect(m.size).toBe(0);
+});
+
+test("never more than max keys, including after they settle", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  for (const k of ["a", "b", "c"]) m(k);
+  for (const c of calls) c.d.resolve(c.key);
+  await tick();
+  expect(m.size).toBe(2);
+});
+
+test("an in-flight key evicted under max does not come back when it settles", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 1 });
+  m("a");
+  m("b");
+  calls[0]!.d.resolve("a");
+  await tick();
+  expect(m.size).toBe(1);
+  m("a");
+  expect(calls).toHaveLength(3);
+});
+
+test("a hit counts as a use for least recently used eviction", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 2 });
+  m("a");
+  m("b");
+  calls[0]!.d.resolve("a");
+  calls[1]!.d.resolve("b");
+  await tick();
+  m("a");
+  m("c");
+  expect(calls).toHaveLength(3);
+  m("a");
+  expect(calls).toHaveLength(3);
+  m("b");
+  expect(calls).toHaveLength(4);
+});
+
+test("expired results are not counted in size or against max", async () => {
+  let t = 0;
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 100, max: 2, now: () => t });
+  m("a");
+  calls[0]!.d.resolve("a");
+  await tick();
+  t = 200;
+  expect(m.size).toBe(0);
+  m("b");
+  m("c");
+  calls[1]!.d.resolve("b");
+  calls[2]!.d.resolve("c");
+  await tick();
+  expect(m.size).toBe(2);
+});
+
+test("a synchronous throw from fn leaves the cache as it was", async () => {
+  const { fn, calls } = lookups();
+  const m = memo((key: string) => {
+    if (key === "b") throw new Error("sync");
+    return fn(key);
+  }, { ttlMs: 1000, max: 1 });
+  const a = m("a");
+  calls[0]!.d.resolve("a");
+  expect(await a).toBe("a");
+  expect(() => m("b")).toThrow("sync");
+  expect(m.size).toBe(1);
+  m("a");
+  expect(calls).toHaveLength(1);
+});
+
+test("matches a reference model over a random sequence of operations", async () => {
+  // mulberry32: a small seeded generator whose output uses all bits, unlike a low-bit LCG.
+  let seed = 42;
+  const rnd = (n: number) => {
+    seed = (seed + 0x6d2b79f5) | 0;
+    let z = Math.imul(seed ^ (seed >>> 15), 1 | seed);
+    z = (z + Math.imul(z ^ (z >>> 7), 61 | z)) ^ z;
+    return (((z ^ (z >>> 14)) >>> 0) % n);
+  };
+  let t = 0;
+  const { fn, calls } = lookups();
+  const ttl = 50;
+  const max = 2;
+  const m = memo(fn, { ttlMs: ttl, max, now: () => t });
+  // Reference: keys in LRU order, each with its settle time (Infinity while in flight) and the call it came from.
+  let model: { key: string; expires: number; call: number }[] = [];
+  const keys = ["a", "b", "c", "d"];
+  const seen = { ops: new Set<number>(), keys: new Set<string>(), evicted: 0 };
+  for (let step = 0; step < 2000; step++) {
+    const op = rnd(4);
+    const key = keys[rnd(keys.length)]!;
+    seen.ops.add(op);
+    seen.keys.add(key);
+    if (op === 0) {
+      // call
+      const hit = model.find((e) => e.key === key);
+      const callsBefore = calls.length;
+      m(key);
+      if (hit && hit.expires > t) {
+        expect(calls.length).toBe(callsBefore);
+        model = [...model.filter((e) => e !== hit), hit];
+      } else {
+        expect(calls.length).toBe(callsBefore + 1);
+        model = model.filter((e) => e.key !== key && e.expires > t);
+        while (model.length >= max) {
+          model.shift();
+          seen.evicted++;
+        }
+        model.push({ key, expires: Infinity, call: calls.length - 1 });
+      }
+    } else if (op === 1) {
+      // invalidate
+      m.invalidate(key);
+      model = model.filter((e) => e.key !== key);
+    } else if (op === 2) {
+      // settle the oldest unsettled call, if any
+      const pending = calls.find((c) => !(c as { done?: boolean }).done);
+      if (pending) {
+        (pending as { done?: boolean }).done = true;
+        pending.d.resolve(pending.key);
+        await tick();
+        const entry = model.find((e) => e.call === calls.indexOf(pending));
+        if (entry) entry.expires = t + ttl;
+      }
+    } else {
+      t += rnd(30);
+    }
+    expect(m.size).toBe(model.filter((e) => e.expires > t).length);
+  }
+  // The run must reach every path, or it checks little.
+  expect([...seen.ops].sort()).toEqual([0, 1, 2, 3]);
+  expect([...seen.keys].sort()).toEqual(keys);
+  expect(seen.evicted).toBeGreaterThan(0);
+  expect(t).toBeGreaterThan(ttl);
+});
